void mutate(uint8_t *buf, size_t offset, int change = 1)
{
    buf[offset] += change;
}

const singleUniverseNode::nodeConfig u1_h{1, sacnPolicy::timeoutPolicy::HOLD};
const singleUniverseNode::nodeConfig u1_s{1, sacnPolicy::timeoutPolicy::STOP};

// push good universe
static void test_push_good_uni()
{
    singleUniverseNode node(u1_h);
    assert(node.processE131Packet(data::sacnView::uni1_ch1_8_255_bytes, sizeof(data::sacnView::uni1_ch1_8_255_bytes), 0));

    std::cout << "test_push_good_uni good\n";
}

// push a packet then pull it
static void test_push_pull_good()
{
    singleUniverseNode node(u1_h);
    const auto &pak = data::sacnView::uni1_ch1_8_255_bytes;

    node.processE131Packet(pak, sizeof(pak), 0);

    sacnData res, tmp;
    assert(node.getLastPacket(&res));

    sacnParse::parse(pak, sizeof(pak), tmp);
    assert(res.universe == tmp.universe);
    assert(memcmp(res.propertyValues, tmp.propertyValues, 512) == 0);
    assert(res.sequenceNumber == tmp.sequenceNumber);

    std::cout << "test_push_pull_good good\n";
}

// push bad then pull -> no changes
static void test_push_pull_bad()
{
    singleUniverseNode node(u1_h);
    const auto &pak1 = data::sacnView::uni1_ch1_8_255_bytes;
    uint8_t pak2[sizeof(pak1)];
    memcpy(pak2, pak1, sizeof(pak2));

    mutate(pak2, constants::offsets::universe);

    node.processE131Packet(pak1, sizeof(pak1), 0);
    node.processE131Packet(pak2, sizeof(pak2), 1000);

    sacnData res, tmp;
    assert(node.getLastPacket(&res));

    sacnParse::parse(pak1, sizeof(pak1), tmp);
    assert(res.universe == tmp.universe);
    assert(memcmp(res.propertyValues, tmp.propertyValues, 512) == 0);
    assert(res.sequenceNumber == tmp.sequenceNumber);

    std::cout << "test_push_pull_bad good\n";
}

// pull without pushing
static void test_pull_never_push()
{
    singleUniverseNode node(u1_h);

    DMXFrame tmp;
    sacnData tmp2;

    assert(!node.getLastFrame(&tmp, 0));
    assert(!node.getLastPacket(&tmp2));

    std::cout << "test_pull_never_push good\n";
}

// push and pull 2 threads
static void test_push_pull_threads()
{

    std::cout << "IMPLEMENT: test_push_pull_threads good\n";
}

// dataloss policy test
static void test_dataloss_stop()
{
    singleUniverseNode node(u1_s);
    const auto &pak = data::sacnView::uni1_ch1_8_255_bytes;

    node.processE131Packet(pak, sizeof(pak), 0);

    DMXFrame out;
    assert(node.getLastFrame(&out, 2499));
    assert(!node.getLastFrame(&out, 2500));
    assert(node.getLastFrame(&out, 0));

    std::cout << "test_dataloss_stop good\n";
}

static void test_sequence_bad()
{
    singleUniverseNode node(u1_h);

    uint8_t pak[sizeof(data::sacnView::uni1_ch1_8_255_bytes)];
    memcpy(pak, data::sacnView::uni1_ch1_8_255_bytes, sizeof(pak));

    node.processE131Packet(pak, sizeof(pak), 0);

    // same packet twice
    assert(!node.processE131Packet(pak, sizeof(pak), 0));

    // packet 19 behind
    mutate(pak, constants::offsets::sequenceNumber, -19);
    assert(!node.processE131Packet(pak, sizeof(pak), 0));

    std::cout << "test_sequence_bad good\n";
}

using state = singleUniverseNode::state;

// frame holds slots 1-512, start code skipped
static void test_frame_contents()
{
    singleUniverseNode node(u1_h);
    const auto &pak = data::sacnView::uni1_ch1_8_255_bytes;
    node.processE131Packet(pak, sizeof(pak), 0);

    DMXFrame out;
    assert(node.getLastFrame(&out, 0));
    for (int i = 0; i < 8; i++)
        assert(out.data[i] == 255);
    for (int i = 8; i < 512; i++)
        assert(out.data[i] == 0);

    std::cout << "test_frame_contents good\n";
}

static void test_state_transitions()
{
    singleUniverseNode node(u1_h);
    const auto &pak = data::sacnView::uni1_ch1_8_255_bytes;
    assert(node.getState() == state::WAITING);

    node.processE131Packet(pak, sizeof(pak), 0);
    assert(node.getState() == state::STREAMING);

    DMXFrame out;
    node.getLastFrame(&out, 2499);
    assert(node.getState() == state::STREAMING);
    node.getLastFrame(&out, 2500);
    assert(node.getState() == state::LOST);

    std::cout << "test_state_transitions good\n";
}

static void test_dataloss_hold()
{
    singleUniverseNode node(u1_h);
    const auto &pak = data::sacnView::uni1_ch1_8_255_bytes;
    node.processE131Packet(pak, sizeof(pak), 0);

    DMXFrame out;
    assert(node.getLastFrame(&out, 2500));
    assert(node.getState() == state::LOST);
    assert(out.data[0] == 255);

    std::cout << "test_dataloss_hold good\n";
}

// while streaming, other sources are ignored and the frame is kept
static void test_cid_lock()
{
    singleUniverseNode node(u1_h);
    uint8_t pak[sizeof(data::sacnView::uni1_ch1_8_255_bytes)];
    memcpy(pak, data::sacnView::uni1_ch1_8_255_bytes, sizeof(pak));
    node.processE131Packet(pak, sizeof(pak), 0);

    mutate(pak, constants::offsets::cid);
    mutate(pak, constants::offsets::sequenceNumber);
    pak[constants::offsets::startCode + 1] = 7;
    assert(!node.processE131Packet(pak, sizeof(pak), 100));

    DMXFrame out;
    assert(node.getLastFrame(&out, 100));
    assert(out.data[0] == 255);

    std::cout << "test_cid_lock good\n";
}

// after loss, a new source takes over from any sequence number
static void test_cid_takeover()
{
    singleUniverseNode node(u1_h);
    uint8_t pak[sizeof(data::sacnView::uni1_ch1_8_255_bytes)];
    memcpy(pak, data::sacnView::uni1_ch1_8_255_bytes, sizeof(pak));
    node.processE131Packet(pak, sizeof(pak), 0);

    DMXFrame out;
    node.getLastFrame(&out, 2500);
    assert(node.getState() == state::LOST);

    mutate(pak, constants::offsets::cid);
    pak[constants::offsets::startCode + 1] = 7;
    // same sequence number as the old source, would be out of order if not reset
    assert(node.processE131Packet(pak, sizeof(pak), 3000));
    assert(node.getState() == state::STREAMING);

    assert(node.getLastFrame(&out, 3000));
    assert(out.data[0] == 7);

    std::cout << "test_cid_takeover good\n";
}

// loss is detected on input too, without a getLastFrame call
static void test_cid_takeover_no_pull()
{
    singleUniverseNode node(u1_h);
    uint8_t pak[sizeof(data::sacnView::uni1_ch1_8_255_bytes)];
    memcpy(pak, data::sacnView::uni1_ch1_8_255_bytes, sizeof(pak));
    node.processE131Packet(pak, sizeof(pak), 0);

    mutate(pak, constants::offsets::cid);
    assert(!node.processE131Packet(pak, sizeof(pak), 2499));
    assert(node.processE131Packet(pak, sizeof(pak), 2500));
    assert(node.getState() == state::STREAMING);

    std::cout << "test_cid_takeover_no_pull good\n";
}

// terminate drops the stream back to waiting, then any source can start a new one
static void test_terminate()
{
    for (auto cfg : {u1_h, u1_s})
    {
        singleUniverseNode node(cfg);
        uint8_t pak[sizeof(data::sacnView::uni1_ch1_8_255_bytes)];
        memcpy(pak, data::sacnView::uni1_ch1_8_255_bytes, sizeof(pak));
        node.processE131Packet(pak, sizeof(pak), 0);

        mutate(pak, constants::offsets::sequenceNumber);
        pak[constants::offsets::options] = constants::OPTIONS_STREAM_TERMINATED;
        assert(!node.processE131Packet(pak, sizeof(pak), 100));
        assert(node.getState() == state::WAITING);

        DMXFrame out;
        assert(!node.getLastFrame(&out, 100));

        // new source, old sequence number
        mutate(pak, constants::offsets::cid);
        pak[constants::offsets::options] = 0;
        assert(node.processE131Packet(pak, sizeof(pak), 200));
        assert(node.getState() == state::STREAMING);
    }

    std::cout << "test_terminate good\n";
}

static void test_bad_bytes()
{
    singleUniverseNode node(u1_h);
    uint8_t pak[sizeof(data::sacnView::uni1_ch1_8_255_bytes)];
    memcpy(pak, data::sacnView::uni1_ch1_8_255_bytes, sizeof(pak));
    mutate(pak, constants::offsets::rootVector);

    assert(!node.processE131Packet(pak, sizeof(pak), 0));
    assert(node.getState() == state::WAITING);

    std::cout << "test_bad_bytes good\n";
}

int main()
{
    test_push_good_uni();
    test_push_pull_good();
    test_push_pull_bad();
    test_pull_never_push();
    test_push_pull_threads();
    test_dataloss_stop();
    test_sequence_bad();
    test_frame_contents();
    test_state_transitions();
    test_dataloss_hold();
    test_cid_lock();
    test_cid_takeover();
    test_cid_takeover_no_pull();
    test_terminate();
    test_bad_bytes();

    std::cout << "All tests passed" << std::endl;
    return 0;
}